// ─── JSON-only error handling ───────────────────────────────────────────────
// The API must never leak PHP warnings or fatal HTML error pages. Suppress
// inline output, then convert uncaught exceptions and fatal errors into JSON.
ini_set('display_errors', '0');
error_reporting(E_ALL);

set_exception_handler(function (Throwable $e): void {
    http_response_code(500);
    if (!headers_sent()) {
        header('Content-Type: application/json; charset=utf-8');
    }
    $msg = $e->getMessage();
    // Same contract as jsonError(): {success:false, message, error}
    echo json_encode(['success' => false, 'message' => $msg, 'error' => $msg]);
    exit;
});

register_shutdown_function(function (): void {
    $err = error_get_last();
    if ($err && in_array($err['type'], [E_ERROR, E_PARSE, E_CORE_ERROR, E_COMPILE_ERROR], true)) {
        http_response_code(500);
        if (!headers_sent()) {
            header('Content-Type: application/json; charset=utf-8');
        }
        $msg = 'Server error: ' . $err['message'];
        // Same contract as jsonError(): {success:false, message, error}
        echo json_encode(['success' => false, 'message' => $msg, 'error' => $msg]);
    }
});

// ─── PDO Connection ─────────────────────────────────────────────────────────
