    $GLOBALS['db_error'] = $e->getMessage();
}

// ─── CORS Headers ───────────────────────────────────────────────────────────
function sendCorsHeaders(): void {
    header('Access-Control-Allow-Origin: *');
    header('Access-Control-Allow-Methods: GET, POST, PUT, DELETE, OPTIONS');
    header('Access-Control-Allow-Headers: Content-Type, Authorization');
    header('Content-Type: application/json; charset=utf-8');

    // API responses must never be cached by the browser/proxy — otherwise a
    // stale GET /devotionals.php response can resurrect a row the admin just
    // deleted ("deleted it, then it came back").
    header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
    header('Pragma: no-cache');

    if ($_SERVER['REQUEST_METHOD'] === 'OPTIONS') {
        http_response_code(200);
        exit;
    }
}

// Resolve the effective HTTP method. Some shared hosts (cPanel/ModSecurity)
// block the DELETE/PUT verbs outright, so the frontend falls back to sending
// POST with ?_method=DELETE (or ?_method=PUT). All DELETE/PUT handlers require
// an admin session, so honoring this override is safe.
function httpMethod(): string {
    $m = strtoupper($_SERVER['REQUEST_METHOD'] ?? 'GET');
    if ($m === 'POST') {
        $override = $_GET['_method'] ?? '';
        if (is_string($override) && in_array(strtoupper($override), ['PUT', 'DELETE'], true)) {
            return strtoupper($override);
        }
    }
    return $m;
}

// ─── JSON Helpers ───────────────────────────────────────────────────────────
function jsonInput(): array {
    $raw = file_get_contents('php://input');
    if (empty($raw)) {
        return [];
    }
    $data = json_decode($raw, true);
    if (!is_array($data)) {
        jsonError('Invalid JSON body', 400);
    }
    return $data;
}

function jsonResponse(mixed $data, int $code = 200): void {
    http_response_code($code);
    // JSON_INVALID_UTF8_SUBSTITUTE: imported DOCX content can contain invalid
    // UTF-8 bytes; without this flag json_encode() returns false and the whole
    // response goes blank — which previously made devotionals "disappear" from
    // the admin dashboard (and homepage) after reload while DB rows remained.
    echo json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
    exit;
}

// ─── UTF-8 Sanitizer ─────────────────────────────────────────────────────────
// Strips invalid UTF-8 byte sequences from imported text (DOCX parsing, manual
// pastes) so JSON responses and json_encode() never fail on bad bytes.
function utf8Safe(mixed $value): mixed {
    if (is_array($value)) {
        foreach ($value as $k => $v) {
            $value[$k] = utf8Safe($v);
        }
        return $value;
    }
    if (is_string($value)) {
        // Fast path: the overwhelming majority of content is already valid
        // UTF-8. A single /u regex check is far cheaper than iconv() per field,
        // so we only pay the iconv cost for genuinely broken strings (imported
        // DOCX content). This makes the GET /devotionals response dramatically
        // faster on shared hosting (hundreds of rows x many fields).
        if (preg_match('//u', $value)) {
            return $value;
        }
        // iconv //IGNORE drops invalid sequences; fall back to regex scrub.
        $clean = @iconv('UTF-8', 'UTF-8//IGNORE', $value);
        if ($clean !== false) {
            return $clean;
        }
        return preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/u', '', $value) ?? $value;
    }
    return $value;
}

function jsonError(string $message, int $code = 400): void {
    // Documented contract: {success: false, message: ...}.
    // 'error' is kept for backward compatibility with older clients.
    jsonResponse([
        'success' => false,
        'message' => $message,
        'error'   => $message,
    ], $code);
}

// ─── Auth Helper ────────────────────────────────────────────────────────────
function requireAdmin(): void {
